BEGIN EXECUTE IMMEDIATE 'DROP TABLE CLIENTES'; EXCEPTION WHEN OTHERS THEN NULL; END;
/
CREATE TABLE CLIENTES (
    ID NUMBER(10),
    NOME VARCHAR(100),
    SOBRENOME VARCHAR(100),
    EMAIL VARCHAR(150),
    TELEFONE VARCHAR(30),
    CPF VARCHAR(20),
    DATA_NASCIMENTO DATE,
    GENERO VARCHAR(10),
    ESTADO_CIVIL VARCHAR(20),
    ENDERECO_LINHA1 VARCHAR(200),
    ENDERECO_LINHA2 VARCHAR(100),
    CIDADE VARCHAR(100),
    ESTADO VARCHAR(5),
    CEP VARCHAR(10),
    PAIS VARCHAR(50)
);

BEGIN EXECUTE IMMEDIATE 'DROP TABLE FUNCIONARIOS'; EXCEPTION WHEN OTHERS THEN NULL; END;
/
CREATE TABLE FUNCIONARIOS (
