    SALARIO NUMBER(12,2),
    DATA_ADMISSAO DATE,
    ENDERECO_LINHA1 VARCHAR(200),
    ENDERECO_LINHA2 VARCHAR(100),
    CIDADE VARCHAR(100),
    ESTADO VARCHAR(5),
    CEP VARCHAR(10),
    BANCO VARCHAR(100),
    CONTA_BANCARIA VARCHAR(30)
);

BEGIN EXECUTE IMMEDIATE 'DROP TABLE CONTAS_BANCARIAS'; EXCEPTION WHEN OTHERS THEN NULL; END;
